sys_script_include.script:
function TargetInstanceAppRepoInstall(grInstance,strAppId,strVersion)
{
	var GetValue = x_snc_devtools.GetValue;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var IsValidSysId = x_snc_devtools.IsValidSysId;
	var IsValidScope = x_snc_devtools.IsValidScope;
	var IsValidVersion = x_snc_devtools.IsValidVersion;
	var MakeUrlParameters = x_snc_devtools.MakeUrlParameters;


	strAppId = GetStringValue(strAppId);
	strVersion = GetStringValue(strVersion);

	if (IsValidSysId(strAppId) == false && IsValidScope(strAppId) == false)
	{
		return false;
	}

	var params = {};
	if (IsValidSysId(strAppId) == true)
	{
		params.sys_id = strAppId;
	}
	else if (IsValidScope(strAppId) == true)
	{
		params.scope = strAppId;
	}
	if (IsValidVersion(strVersion) == true)
	{
		params.version = strVersion;
	}
	strParams = MakeUrlParameters(params);
	var strUrl = 'sn_cicd/app_repo/install?'+strParams;

	var result = TargetInstanceRequest(grInstance,strUrl,'','post');

	var strProgressId = GetValue(result,'result','links','progress','id');

	if (IsValidSysId(strProgressId) == false)
	{
		return false;
	}

	return strProgressId;	
}
